 13	  const listeners=new Set<()=>void>();
 14	  const notify=()=>listeners.forEach(listener=>listener());
 15	  const ready=(data:unknown):Entry=>({state:{data,hasData:true,status:'ready',error:null}});
 16	  for (const [key,value] of Object.entries(initial.resources)) entries.set(key,ready(value));
 17	  const replace=(key:string,entry?:Entry)=>{
 18	    const old=entries.get(key);
 19	    if(entry) entries.set(key,entry); else entries.delete(key);
 20	    old?.controller?.abort();notify();
 21	  };
 22	  const invalidateMany=(keys:readonly string[])=>{
 23	    const previous:Entry[]=[];
 24	    for(const key of new Set(keys)) {
 25	      const entry=entries.get(key);
 26	      if(entry){previous.push(entry);entries.delete(key);}
 27	    }
 28	    if(!previous.length)return;
 29	    // Detach the entire batch before abort listeners can publish newer data.
 30	    // A late response must not restore an old sibling or overwrite that owner.
 31	    previous.forEach(entry=>entry.controller?.abort());notify();
