 35	    read<T>(key:string):RouteSnapshot<T>{return (entries.get(key)?.state ?? empty) as RouteSnapshot<T>;},
 36	    subscribe(listener:()=>void){listeners.add(listener);return ()=>{listeners.delete(listener)};},
